mapper.select:
SELECT c.id AS chunk_id, c.doc_id, c.version_id, c.chunk_index, c.content, c.heading_path, c.page_no, d.title AS doc_title, ts_rank_cd(c.tsv, to_tsquery('simple', #{tsQuery}), 32) AS rank FROM biz_doc_chunk c JOIN biz_document d ON d.id = c.doc_id AND d.status = 'PUBLISHED' AND d.deleted_at IS NULL LEFT JOIN biz_category_perm p ON p.category_id = d.category_id AND p.role_id IN #{rid} WHERE c.is_active = true AND c.tsv IS NOT NULL AND c.tsv @@ to_tsquery('simple', #{tsQuery})
AND d.category_id = #{categoryId}
AND p.category_id IS NOT NULL ORDER BY rank DESC LIMIT #{limit}

SELECT c.id AS chunk_id, c.doc_id, c.version_id, c.chunk_index, c.content, c.heading_path, c.page_no, d.title AS doc_title, c.embedding AS embedding_text, 0.0 AS rank FROM biz_doc_chunk c JOIN biz_document d ON d.id = c.doc_id AND d.status = 'PUBLISHED' AND d.deleted_at IS NULL LEFT JOIN biz_category_perm p ON p.category_id = d.category_id AND p.role_id IN #{rid} WHERE c.is_active = true AND c.embedding IS NOT NULL
AND d.category_id = #{categoryId}
AND p.category_id IS NOT NULL ORDER BY c.id DESC LIMIT #{limit}
